for (const locale of Object.keys(requestErrorTranslations) as Array<Exclude<Locale, "nl">>) {
  Object.assign(additionalTranslations[locale], requestErrorTranslations[locale]);
}
for (const locale of Object.keys(completionTranslations) as Array<Exclude<Locale, "nl">>) {
  Object.assign(additionalTranslations[locale], completionTranslations[locale]);
}
for (const locale of Object.keys(pageTranslations) as Array<Exclude<Locale, "nl">>) {
  Object.assign(additionalTranslations[locale], pageTranslations[locale]);
}

for (const locale of locales.filter((item): item is Exclude<Locale, "nl"> => item !== "nl")) {
  Object.assign(translations[locale], additionalTranslations[locale]);
}

export function translate(value: string, locale: Locale) {
  if (locale === "nl") return value;
  return translations[locale][value] ?? value;
}

/** Translate both standalone labels and Dutch fragments inside mixed text nodes. */
export function translateText(value: string, locale: Locale) {
  if (locale === "nl") return value;
  return Object.entries(translations[locale])
    .filter(([source, target]) => source.length >= 4 && source !== target)
    .sort(([a], [b]) => b.length - a.length)
    .reduce((result, [source, target]) => {
      const escaped = source.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const pattern = new RegExp(
        `(?<![\\p{L}\\p{N}])${escaped}(?![\\p{L}\\p{N}])`,
        "gu",
      );
      return result.replace(pattern, target);
    }, value);
}
